//! Modeless Timeline Sequencer workspace (ADR 0126).

use crate::timeline_editor::{
    TimelineClipGesture, TimelineClipGestureKind, TimelineEditorState, TimelinePreviewMode,
    TimelineSelection, TimelineSnapMode, TimelineTrackViewState,
};
use crate::ui::*;
use engine::timeline::{TimelineLoop, TimelineTick, TIMELINE_TICKS_PER_SECOND};
use engine_authoring::{
    timeline_track_registry, AnimationSet, TimelineBinding, TimelineClip, TimelineClipPayload,
    TimelineMarker, TimelinePropertyKey, TimelinePropertyValue, TimelineTrack, TimelineTrackKind,
};

pub(in crate::ui) fn timeline_window_id() -> egui::Id {
    egui::Id::new("timeline_sequencer_window")
}

impl EditorApp {
    pub(in crate::ui) fn open_timeline_editor(
        &mut self,
        relative_path: PathBuf,
        absolute_path: PathBuf,
    ) -> Result<(), String> {
        let asset_id = self
            .asset_manifest
            .iter()
            .find(|(_, entry)| Path::new(&entry.path) == relative_path.as_path())
            .map(|(id, _)| id.clone());
        let state = TimelineEditorState::open(relative_path, absolute_path, asset_id)?;
        self.timeline_editor = Some(state);
        self.selected_asset = None;
        Ok(())
    }

    pub(in crate::ui) fn show_timeline_editor_window(&mut self, context: &egui::Context) {
        let Some(mut state) = self.timeline_editor.take() else {
            self.scene_view.set_timeline_preview_request(None);
            return;
        };

        if let Some(status) = self.scene_view.timeline_preview_status().cloned() {
            state.update_preview_tick(status.tick, status.state);
            if let Some(message) = status.diagnostics.last() {
                state.status = Some(message.clone());
            }
        }

        let mut open = true;
        let dirty = if state.is_dirty() { " *" } else { "" };
        let title = format!("Sequencer — {}{dirty}", state.relative_path().display());
        egui::Window::new(title)
            .id(timeline_window_id())
            .open(&mut open)
            .default_size(egui::vec2(1080.0, 650.0))
            .min_size(egui::vec2(720.0, 420.0))
            .show(context, |ui| {
                self.show_timeline_toolbar(ui, &mut state);
                ui.separator();
                self.show_timeline_workspace(ui, &mut state);
            });

        if open {
            self.publish_timeline_preview(&state);
            self.timeline_editor = Some(state);
        } else {
            self.scene_view.set_timeline_preview_request(None);
        }
    }

    fn show_timeline_toolbar(&mut self, ui: &mut egui::Ui, state: &mut TimelineEditorState) {
        ui.horizontal_wrapped(|ui| {
            if ui.button("Save").clicked() {
                match state.save() {
                    Ok(()) => state.status = Some("Timeline saved".to_owned()),
                    Err(error) => state.status = Some(error.to_string()),
                }
            }
            if ui
                .add_enabled(state.can_undo(), egui::Button::new("Undo"))
                .clicked()
            {
                state.undo();
            }
            if ui
                .add_enabled(state.can_redo(), egui::Button::new("Redo"))
                .clicked()
            {
                state.redo();
            }
            ui.separator();
            if ui.button("⏮").on_hover_text("Stop and return to zero").clicked() {
                state.playhead = TimelineTick::ZERO;
                state.preview_mode = TimelinePreviewMode::Stopped;
            }
            if ui.button("◀|").on_hover_text("Step backward one display frame").clicked() {
                state.playhead = state
                    .playhead
                    .saturating_add(-state.frame_ticks())
                    .clamp(TimelineTick::ZERO, state.document().duration);
                state.preview_mode = TimelinePreviewMode::Paused;
            }
            if state.preview_mode == TimelinePreviewMode::Playing {
                if ui.button("⏸").on_hover_text("Pause").clicked() {
                    state.preview_mode = TimelinePreviewMode::Paused;
                }
            } else if ui.button("▶").on_hover_text("Play").clicked() {
                state.preview_mode = TimelinePreviewMode::Playing;
            }
            if ui.button("|▶").on_hover_text("Step forward one display frame").clicked() {
                state.playhead = state
                    .playhead
                    .saturating_add(state.frame_ticks())
                    .clamp(TimelineTick::ZERO, state.document().duration);
                state.preview_mode = TimelinePreviewMode::Paused;
            }
            ui.separator();
            ui.checkbox(&mut state.preview_events, "Preview Events")
                .on_hover_text("Manual scrub suppresses sequence side effects unless explicitly enabled");
            ui.checkbox(&mut state.loop_enabled, "Loop");
            egui::ComboBox::from_id_salt("timeline_rate")
                .selected_text(format!("{:.2}×", state.playback_rate))
                .show_ui(ui, |ui| {
                    for rate in [0.25_f32, 0.5, 1.0, 2.0, 4.0] {
                        ui.selectable_value(&mut state.playback_rate, rate, format!("{rate:.2}×"));
                    }
                });
            ui.separator();
            ui.checkbox(&mut state.snap_enabled, "Snap");
            egui::ComboBox::from_id_salt("timeline_snap_mode")
                .selected_text(match state.snap_mode {
                    TimelineSnapMode::Frames => "Frames",
                    TimelineSnapMode::Seconds => "Seconds",
                    TimelineSnapMode::Custom => "Custom",
                })
                .show_ui(ui, |ui| {
                    ui.selectable_value(&mut state.snap_mode, TimelineSnapMode::Frames, "Frames");
                    ui.selectable_value(&mut state.snap_mode, TimelineSnapMode::Seconds, "Seconds");
                    ui.selectable_value(&mut state.snap_mode, TimelineSnapMode::Custom, "Custom");
                });
            if state.snap_mode == TimelineSnapMode::Custom {
                ui.add(
                    egui::DragValue::new(&mut state.custom_snap_ticks)
                        .range(1..=TIMELINE_TICKS_PER_SECOND * 60)
                        .suffix(" ticks"),
                );
            }
            ui.add(egui::Slider::new(&mut state.zoom, 0.1..=16.0).logarithmic(true).text("Zoom"));
            let seconds = state.playhead.to_seconds_f64();
            let frame = state.playhead.get().div_euclid(state.frame_ticks().max(1));
            ui.monospace(format!("{seconds:.3} s  |  frame {frame}  |  tick {}", state.playhead.get()));
        });

        if state.loop_enabled {
            ui.horizontal(|ui| {
                ui.label("Loop region");
                let mut start = state.loop_start.get();
                let mut end = state.loop_end.get();
                if ui.add(egui::DragValue::new(&mut start).speed(state.frame_ticks() as f64)).changed() {
                    state.loop_start = TimelineTick::new(start)
                        .clamp(TimelineTick::ZERO, state.document().duration);
                }
                if ui.add(egui::DragValue::new(&mut end).speed(state.frame_ticks() as f64)).changed() {
                    state.loop_end = TimelineTick::new(end)
                        .clamp(TimelineTick::ZERO, state.document().duration);
                }
                if state.loop_end <= state.loop_start {
                    state.loop_end = state
                        .loop_start
                        .saturating_add(state.frame_ticks().max(1))
                        .clamp(TimelineTick::ZERO, state.document().duration);
                }
            });
        }

        if let Some(status) = &state.status {
            ui.small(status);
        }
    }

    fn show_timeline_workspace(&mut self, ui: &mut egui::Ui, state: &mut TimelineEditorState) {
        let available = ui.available_size();
        let inspector_width = 270.0_f32.min((available.x * 0.3).max(220.0));
        ui.horizontal_top(|ui| {
            ui.allocate_ui_with_layout(
                egui::vec2((available.x - inspector_width - 8.0).max(360.0), available.y),
                egui::Layout::top_down(egui::Align::Min),
                |ui| self.show_timeline_lanes(ui, state),
            );
            ui.separator();
            ui.allocate_ui_with_layout(
                egui::vec2(inspector_width, available.y),
                egui::Layout::top_down(egui::Align::Min),
                |ui| self.show_timeline_inspector(ui, state),
            );
        });
    }

    fn show_timeline_lanes(&mut self, ui: &mut egui::Ui, state: &mut TimelineEditorState) {
        ui.horizontal(|ui| {
            ui.menu_button("+ Track", |ui| {
                ui.add(egui::TextEdit::singleline(&mut state.add_track_search).hint_text("Search track types…"));
                let selected_entity = self.selected_entity.clone();
                let query = state.add_track_search.trim().to_ascii_lowercase();
                for descriptor in timeline_track_registry() {
                    if !query.is_empty()
                        && !descriptor.label.to_ascii_lowercase().contains(&query)
                        && !descriptor.type_id.to_ascii_lowercase().contains(&query)
                    {
                        continue;
                    }
                    let needs_entity = matches!(
                        descriptor.kind,
                        TimelineTrackKind::Animation
                            | TimelineTrackKind::TransformProperty
                            | TimelineTrackKind::CameraCut
                            | TimelineTrackKind::Vfx
                    );
                    let enabled = !needs_entity || selected_entity.is_some();
                    if ui
                        .add_enabled(enabled, egui::Button::new(descriptor.label))
                        .on_disabled_hover_text("Select a scene entity first so the stable binding is explicit")
                        .clicked()
                    {
                        let binding = if needs_entity {
                            selected_entity.clone().map(|entity| TimelineBinding::Entity { entity })
                        } else {
                            None
                        };
                        let track = TimelineTrack {
                            id: engine_authoring::TimelineTrackId::generate(),
                            name: descriptor.label.to_owned(),
                            kind: descriptor.kind,
                            enabled: true,
                            binding,
                            clips: Vec::new(),
                        };
                        if let Err(error) = state.apply(vec![engine_authoring::TimelineAuthoringCommand::AddTrack(track)]) {
                            state.status = Some(error.to_string());
                        }
                        ui.close();
                    }
                }
            });
            if ui.button("+ Marker").clicked() {
                let marker = TimelineMarker {
                    id: engine_authoring::TimelineMarkerId::generate(),
                    name: "Marker".to_owned(),
                    tick: state.playhead,
                    event: None,
                };
                if let Err(error) = state.apply(vec![engine_authoring::TimelineAuthoringCommand::AddMarker(marker.clone())]) {
                    state.status = Some(error.to_string());
                } else {
                    state.selection = Some(TimelineSelection::Marker(marker.id));
                }
            }
            if ui
                .add_enabled(!state.selected_clips.is_empty(), egui::Button::new("Duplicate"))
                .clicked()
                && let Err(error) = state.duplicate_selected_clips()
            {
                state.status = Some(error.to_string());
            }
            if ui
                .add_enabled(!state.selected_clips.is_empty(), egui::Button::new("Delete"))
                .clicked()
                && let Err(error) = state.delete_selected_clips()
            {
                state.status = Some(error.to_string());
            }
        });

        let tracks = state.document().tracks.clone();
        let markers = state.document().markers.clone();
        let duration = state.document().duration.max(TimelineTick::new(1));
        let left_width = 230.0;
        let row_height = 34.0;
        let ruler_height = 38.0;

        egui::ScrollArea::vertical().show(ui, |ui| {
            ui.horizontal(|ui| {
                ui.allocate_ui(egui::vec2(left_width, ruler_height), |ui| {
                    ui.strong("Tracks");
                });
                let (ruler_rect, ruler_response) = ui.allocate_exact_size(
                    egui::vec2(ui.available_width().max(320.0), ruler_height),
                    egui::Sense::click_and_drag(),
                );
                draw_timeline_ruler(ui, state, ruler_rect, duration, &markers);
                if (ruler_response.clicked() || ruler_response.dragged())
                    && let Some(pointer) = ruler_response.interact_pointer_pos()
                {
                    let tick = timeline_tick_at_x(state, ruler_rect, pointer.x, duration);
                    let (tick, _) = state.snap_tick(tick, &[]);
                    state.playhead = tick;
                    state.preview_mode = TimelinePreviewMode::Paused;
                }
            });

            ui.horizontal(|ui| {
                ui.allocate_ui(egui::vec2(left_width, row_height), |ui| {
                    ui.label("Markers / Events");
                });
                let (rect, response) = ui.allocate_exact_size(
                    egui::vec2(ui.available_width().max(320.0), row_height),
                    egui::Sense::click_and_drag(),
                );
                draw_marker_lane(ui, state, rect, &markers);
                if response.clicked() && let Some(pointer) = response.interact_pointer_pos() {
                    state.playhead = timeline_tick_at_x(state, rect, pointer.x, duration);
                    state.preview_mode = TimelinePreviewMode::Paused;
                }
                for marker in &markers {
                    let x = timeline_x(state, rect, marker.tick);
                    if x < rect.left() - 8.0 || x > rect.right() + 8.0 {
                        continue;
                    }
                    let handle = egui::Rect::from_center_size(
                        egui::pos2(x, rect.center().y),
                        egui::vec2(12.0, row_height - 4.0),
                    );
                    let marker_response = ui.interact(
                        handle,
                        ui.make_persistent_id(("timeline_marker", marker.id.as_str())),
                        egui::Sense::click_and_drag(),
                    );
                    if marker_response.clicked() {
                        state.selection = Some(TimelineSelection::Marker(marker.id.clone()));
                    }
                    if marker_response.dragged() {
                        let raw = TimelineTick::new(
                            marker.tick.get().saturating_add(
                                (marker_response.drag_delta().x as f64 * state.ticks_per_pixel()).round() as i64,
                            ),
                        );
                        let (tick, _) = state.snap_tick(raw, &[]);
                        if let Err(error) = state.apply(vec![engine_authoring::TimelineAuthoringCommand::MoveMarker {
                            marker: marker.id.clone(),
                            tick,
                        }]) {
                            state.status = Some(error.to_string());
                        }
                    }
                }
            });

            for track in tracks {
                ui.horizontal(|ui| {
                    ui.allocate_ui(egui::vec2(left_width, row_height), |ui| {
                        self.show_timeline_track_header(ui, state, &track);
                    });
                    let (lane_rect, lane_response) = ui.allocate_exact_size(
                        egui::vec2(ui.available_width().max(320.0), row_height),
                        egui::Sense::click(),
                    );
                    draw_timeline_lane_background(ui, state, lane_rect);
                    if lane_response.clicked() && let Some(pointer) = lane_response.interact_pointer_pos() {
                        state.playhead = timeline_tick_at_x(state, lane_rect, pointer.x, duration);
                        state.preview_mode = TimelinePreviewMode::Paused;
                    }

                    if let Some(payload) = super::super::hierarchy::release_drag_payload_in_rect::<DragPayload>(ui, lane_rect) {
                        if let Err(message) = add_timeline_asset_clip(
                            state,
                            self.project_root.as_ref(),
                            &track,
                            payload.as_ref(),
                        ) {
                            state.status = Some(message);
                        }
                    }

                    let extra_edges = track
                        .clips
                        .iter()
                        .flat_map(|clip| [clip.start, clip.end()])
                        .collect::<Vec<_>>();
                    for clip in &track.clips {
                        self.show_timeline_clip(ui, state, &track, clip, lane_rect, &extra_edges);
                    }

                    if let Some(gesture) = &state.clip_gesture
                        && let Some(snap) = gesture.snap_target
                    {
                        let x = timeline_x(state, lane_rect, snap);
                        ui.painter().line_segment(
                            [egui::pos2(x, lane_rect.top()), egui::pos2(x, lane_rect.bottom())],
                            egui::Stroke::new(1.5, egui::Color32::YELLOW),
                        );
                    }
                    let playhead_x = timeline_x(state, lane_rect, state.playhead);
                    ui.painter().line_segment(
                        [egui::pos2(playhead_x, lane_rect.top()), egui::pos2(playhead_x, lane_rect.bottom())],
                        egui::Stroke::new(1.0, egui::Color32::from_rgb(255, 110, 90)),
                    );
                });
            }
        });

        ui.separator();
        ui.horizontal(|ui| {
            ui.label("Horizontal scroll");
            let mut view = state.view_start.get();
            if ui
                .add(egui::Slider::new(&mut view, 0..=duration.get().max(0)).show_value(false))
                .changed()
            {
                state.view_start = TimelineTick::new(view);
            }
        });
    }

    fn show_timeline_track_header(
        &mut self,
        ui: &mut egui::Ui,
        state: &mut TimelineEditorState,
        track: &TimelineTrack,
    ) {
        let selected = matches!(state.selection.as_ref(), Some(TimelineSelection::Track(id)) if id == &track.id);
        let mut view = state.track_view.get(&track.id).copied().unwrap_or_default();
        ui.horizontal(|ui| {
            if ui.selectable_label(selected, &track.name).clicked() {
                state.selection = Some(TimelineSelection::Track(track.id.clone()));
            }
            let muted = ui.selectable_label(view.muted, "M").on_hover_text("Transient mute; not persisted");
            if muted.clicked() { view.muted = !view.muted; }
            let solo = ui.selectable_label(view.solo, "S").on_hover_text("Transient solo; not persisted");
            if solo.clicked() { view.solo = !view.solo; }
            let locked = ui.selectable_label(view.locked, "L").on_hover_text("Lock lane editing in this Sequencer view");
            if locked.clicked() { view.locked = !view.locked; }
            if let Some(binding) = &track.binding {
                ui.small(binding_label(binding));
            }
            if ui.small_button("+").on_hover_text("Add a default clip at the playhead").clicked() {
                match default_timeline_clip(state, track) {
                    Some(clip) => {
                        if let Err(error) = state.apply(vec![engine_authoring::TimelineAuthoringCommand::AddClip {
                            track: track.id.clone(),
                            clip,
                        }]) {
                            state.status = Some(error.to_string());
                        }
                    }
                    None => state.status = Some("Drop a compatible Animation Set, Audio, or VFX asset onto this lane".to_owned()),
                }
            }
        });
        state.track_view.insert(track.id.clone(), view);
    }

    fn show_timeline_clip(
        &mut self,
        ui: &mut egui::Ui,
        state: &mut TimelineEditorState,
        track: &TimelineTrack,
        clip: &TimelineClip,
        lane_rect: egui::Rect,
        extra_edges: &[TimelineTick],
    ) {
        let locked = state
            .track_view
            .get(&track.id)
            .is_some_and(|view| view.locked);
        let mut start = clip.start;
        let mut duration = clip.duration;
        if let Some(gesture) = state.clip_gesture.as_ref().filter(|gesture| gesture.clip == clip.id) {
            start = gesture.draft_start;
            duration = gesture.draft_duration;
        }
        let left = timeline_x(state, lane_rect, start);
        let right = timeline_x(state, lane_rect, start.saturating_add(duration.get()));
        let clip_rect = egui::Rect::from_min_max(
            egui::pos2(left.max(lane_rect.left()), lane_rect.top() + 4.0),
            egui::pos2(right.min(lane_rect.right()).max(left + 4.0), lane_rect.bottom() - 4.0),
        );
        if !lane_rect.intersects(clip_rect) {
            return;
        }
        let selected = state.selected_clips.contains(&clip.id);
        let color = timeline_track_color(track.kind, selected);
        ui.painter().rect_filled(clip_rect, 4.0, color);
        ui.painter().rect_stroke(
            clip_rect,
            4.0,
            egui::Stroke::new(if selected { 2.0 } else { 1.0 }, egui::Color32::WHITE),
            egui::StrokeKind::Inside,
        );
        ui.painter().text(
            clip_rect.left_center() + egui::vec2(8.0, 0.0),
            egui::Align2::LEFT_CENTER,
            &clip.name,
            egui::TextStyle::Small.resolve(ui.style()),
            egui::Color32::WHITE,
        );

        let body = ui.interact(
            clip_rect.shrink2(egui::vec2(7.0, 0.0)),
            ui.make_persistent_id(("timeline_clip", clip.id.as_str())),
            if locked { egui::Sense::click() } else { egui::Sense::click_and_drag() },
        );
        if body.clicked() {
            let additive = ui.input(|input| input.modifiers.ctrl || input.modifiers.command);
            state.select_clip(clip.id.clone(), additive);
        }
        if !locked {
            handle_clip_gesture(ui, state, clip, &body, TimelineClipGestureKind::Move, extra_edges);
            let left_handle = egui::Rect::from_min_max(clip_rect.min, egui::pos2(clip_rect.left() + 7.0, clip_rect.bottom()));
            let left_response = ui.interact(
                left_handle,
                ui.make_persistent_id(("timeline_trim_start", clip.id.as_str())),
                egui::Sense::click_and_drag(),
            );
            handle_clip_gesture(ui, state, clip, &left_response, TimelineClipGestureKind::TrimStart, extra_edges);
            let right_handle = egui::Rect::from_min_max(
                egui::pos2(clip_rect.right() - 7.0, clip_rect.top()),
                clip_rect.max,
            );
            let right_response = ui.interact(
                right_handle,
                ui.make_persistent_id(("timeline_trim_end", clip.id.as_str())),
                egui::Sense::click_and_drag(),
            );
            handle_clip_gesture(ui, state, clip, &right_response, TimelineClipGestureKind::TrimEnd, extra_edges);
        }
    }

    fn show_timeline_inspector(&mut self, ui: &mut egui::Ui, state: &mut TimelineEditorState) {
        ui.heading("Inspector");
        let selection = state.selection.clone();
        match selection {
            Some(TimelineSelection::Track(id)) => {
                let Some(track) = state.document().tracks.iter().find(|track| track.id == id).cloned() else { return; };
                ui.label(format!("{} track", track_kind_label(track.kind)));
                let mut name = track.name.clone();
                if ui.text_edit_singleline(&mut name).changed() {
                    apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::RenameTrack { track: id.clone(), name }]);
                }
                let mut enabled = track.enabled;
                if ui.checkbox(&mut enabled, "Enabled in Play").changed() {
                    apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::SetTrackEnabled { track: id.clone(), enabled }]);
                }
                ui.label(format!("Seek: {:?}", track.kind.seek_capability()));
                if let Some(binding) = &track.binding {
                    ui.monospace(binding_label(binding));
                    if let TimelineBinding::Entity { entity } = binding
                        && ui.button("Focus bound entity").clicked()
                    {
                        self.select_single_entity(Some(entity.clone()));
                        if let Some(scene) = self.session.scene() {
                            self.scene_view.focus_entity(scene, entity);
                        }
                    }
                } else {
                    ui.weak("No stable binding");
                }
                if let Some(entity) = self.selected_entity.clone()
                    && ui.button("Bind selected entity").clicked()
                {
                    apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::SetBinding {
                        track: id.clone(),
                        binding: Some(TimelineBinding::Entity { entity }),
                    }]);
                }
                if ui.button("Clear binding").clicked() {
                    apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::SetBinding {
                        track: id.clone(),
                        binding: None,
                    }]);
                }
            }
            Some(TimelineSelection::Clip(id)) => self.show_timeline_clip_inspector(ui, state, &id),
            Some(TimelineSelection::Marker(id)) => {
                let Some(marker) = state.document().markers.iter().find(|marker| marker.id == id).cloned() else { return; };
                ui.label(&marker.name);
                let mut tick = marker.tick.get();
                if ui.add(egui::DragValue::new(&mut tick)).changed() {
                    apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::MoveMarker {
                        marker: id.clone(),
                        tick: TimelineTick::new(tick).clamp(TimelineTick::ZERO, state.document().duration),
                    }]);
                }
                let mut event = marker.event.clone().unwrap_or_default();
                let mut emits = marker.event.is_some();
                if ui.checkbox(&mut emits, "Emit sequence event").changed() {
                    apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::SetMarkerEvent {
                        marker: id.clone(),
                        event: emits.then_some(if event.is_empty() { "timeline.marker".to_owned() } else { event.clone() }),
                    }]);
                }
                if emits && ui.text_edit_singleline(&mut event).changed() {
                    apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::SetMarkerEvent { marker: id.clone(), event: Some(event) }]);
                }
                if ui.button("Delete marker").clicked() {
                    apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::RemoveMarker(id)]);
                    state.selection = None;
                }
            }
            None => ui.weak("Select a track, clip, or marker"),
        }

        ui.separator();
        ui.heading("Diagnostics");
        let diagnostics = state.diagnostics();
        if diagnostics.is_empty() {
            ui.weak("No Timeline diagnostics");
        } else {
            for diagnostic in diagnostics {
                ui.label(format!("[{}] {}", diagnostic.code, diagnostic.message));
            }
        }
    }

    fn show_timeline_clip_inspector(
        &mut self,
        ui: &mut egui::Ui,
        state: &mut TimelineEditorState,
        id: &engine_authoring::TimelineClipId,
    ) {
        let Some((track_id, clip)) = state.clip(id).map(|(track, clip)| (track.clone(), clip.clone())) else { return; };
        let kind = state
            .document()
            .tracks
            .iter()
            .find(|track| track.id == track_id)
            .map(|track| track.kind)
            .unwrap_or(clip.payload.kind());
        ui.label(format!("{} clip", track_kind_label(kind)));
        let mut name = clip.name.clone();
        if ui.text_edit_singleline(&mut name).changed() {
            apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::RenameClip { clip: id.clone(), name }]);
        }
        let mut start = clip.start.get();
        if ui.add(egui::DragValue::new(&mut start).prefix("Start " )).changed() {
            apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::MoveClip {
                clip: id.clone(),
                start: TimelineTick::new(start).clamp(TimelineTick::ZERO, state.document().duration),
            }]);
        }
        let mut duration = clip.duration.get();
        if ui.add(egui::DragValue::new(&mut duration).range(1..=i64::MAX).prefix("Duration " )).changed() {
            apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::ResizeClip {
                clip: id.clone(),
                duration: TimelineTick::new(duration.max(1)),
            }]);
        }
        let mut payload = clip.payload.clone();
        let mut payload_changed = false;
        match &mut payload {
            TimelineClipPayload::Animation { animation_set, motion_slot } => {
                ui.monospace(format!("Set: {}", animation_set.as_str()));
                ui.monospace(format!("Slot: {}", motion_slot.as_str()));
                ui.small("Drop another Animation Set on the lane to author a new motion clip.");
            }
            TimelineClipPayload::TransformProperty { property, keys } => {
                egui::ComboBox::from_id_salt(("timeline_property", id.as_str()))
                    .selected_text(property.as_str())
                    .show_ui(ui, |ui| {
                        for descriptor in engine_authoring::timeline_property_registry() {
                            payload_changed |= ui
                                .selectable_value(property, descriptor.type_id.to_owned(), descriptor.label)
                                .changed();
                        }
                    });
                show_curve_editor(ui, keys, clip.duration, &mut payload_changed);
            }
            TimelineClipPayload::CameraCut => {
                ui.small("Camera selection is a transient runtime override; persisted camera priorities are untouched.");
            }
            TimelineClipPayload::Event { name, payload } => {
                ui.label("Event name");
                payload_changed |= ui.text_edit_singleline(name).changed();
                ui.label("Payload");
                payload_changed |= ui.text_edit_multiline(payload).changed();
            }
            TimelineClipPayload::Audio { clip, volume, looping } => {
                ui.monospace(format!("Audio: {}", clip.as_str()));
                payload_changed |= ui.add(egui::Slider::new(volume, 0.0..=4.0).text("Volume")).changed();
                payload_changed |= ui.checkbox(looping, "Loop while active").changed();
                ui.small("Audio is NonSeekable unless the runtime owner exposes a meaningful cursor; scrub never fabricates one.");
            }
            TimelineClipPayload::Vfx { effect, looping } => {
                ui.monospace(format!("VFX: {}", effect.as_str()));
                payload_changed |= ui.checkbox(looping, "Loop while active").changed();
                ui.small("ReplayRequired VFX is reconstructed through the production external clock.");
            }
        }
        if payload_changed {
            apply_timeline_commands(state, vec![engine_authoring::TimelineAuthoringCommand::SetClipPayload {
                clip: id.clone(),
                payload,
            }]);
        }
    }

    fn publish_timeline_preview(&mut self, state: &TimelineEditorState) {
        if self.is_playing() {
            self.scene_view.set_timeline_preview_request(None);
            return;
        }
        let Some(asset) = state.asset_id().cloned() else {
            self.scene_view.set_timeline_preview_request(None);
            return;
        };
        let playback = match state.preview_mode {
            TimelinePreviewMode::Stopped => crate::scene_view::TimelinePreviewPlayback::Stopped,
            TimelinePreviewMode::Paused => crate::scene_view::TimelinePreviewPlayback::Paused,
            TimelinePreviewMode::Playing => crate::scene_view::TimelinePreviewPlayback::Playing,
        };
        let (rate_numerator, rate_denominator) = rational_preview_rate(state.playback_rate);
        let loop_range = if state.loop_enabled && state.loop_start < state.loop_end {
            Some(TimelineLoop { start: state.loop_start, end: state.loop_end })
        } else {
            None
        };
        self.scene_view.set_timeline_preview_request(Some(crate::scene_view::TimelinePreviewRequest {
            asset,
            document: state.preview_document(),
            tick: state.playhead,
            playback,
            preview_events: state.preview_events,
            rate_numerator,
            rate_denominator,
            loop_range,
        }));
    }
}

fn apply_timeline_commands(
    state: &mut TimelineEditorState,
    commands: Vec<engine_authoring::TimelineAuthoringCommand>,
) {
    if let Err(error) = state.apply(commands) {
        state.status = Some(error.to_string());
    }
}

fn default_timeline_clip(state: &TimelineEditorState, track: &TimelineTrack) -> Option<TimelineClip> {
    let duration = TimelineTick::new(state.frame_ticks().max(1));
    let payload = match track.kind {
        TimelineTrackKind::CameraCut => TimelineClipPayload::CameraCut,
        TimelineTrackKind::Event => TimelineClipPayload::Event {
            name: "timeline.event".to_owned(),
            payload: String::new(),
        },
        TimelineTrackKind::TransformProperty => TimelineClipPayload::TransformProperty {
            property: "engine.transform.translation".to_owned(),
            keys: vec![
                TimelinePropertyKey { tick: TimelineTick::ZERO, value: TimelinePropertyValue::Vec3([0.0; 3]) },
                TimelinePropertyKey { tick: duration, value: TimelinePropertyValue::Vec3([0.0; 3]) },
            ],
        },
        TimelineTrackKind::Animation | TimelineTrackKind::Audio | TimelineTrackKind::Vfx => return None,
    };
    Some(TimelineClip {
        id: engine_authoring::TimelineClipId::generate(),
        name: track_kind_label(track.kind).to_owned(),
        start: state.playhead,
        duration,
        source_offset: TimelineTick::ZERO,
        payload,
    })
}

fn add_timeline_asset_clip(
    state: &mut TimelineEditorState,
    root: Option<&ProjectRoot>,
    track: &TimelineTrack,
    dropped: &DragPayload,
) -> Result<(), String> {
    let payload = match (track.kind, dropped.kind) {
        (TimelineTrackKind::Audio, AssetKind::Audio) => TimelineClipPayload::Audio {
            clip: dropped.asset_id.clone(),
            volume: 1.0,
            looping: false,
        },
        (TimelineTrackKind::Vfx, AssetKind::Vfx) => TimelineClipPayload::Vfx {
            effect: dropped.asset_id.clone(),
            looping: false,
        },
        (TimelineTrackKind::Animation, AssetKind::AnimationSet) => {
            let root = root.ok_or_else(|| "Open a project before resolving Animation Set slots".to_owned())?;
            let json = fs::read_to_string(root.assets_root().join(&dropped.relative_path))
                .map_err(|error| error.to_string())?;
            let set = AnimationSet::from_json(&json).map_err(|error| error.to_string())?;
            let motion_slot = set
                .bindings
                .keys()
                .next()
                .cloned()
                .ok_or_else(|| "The dropped Animation Set has no bound motion slots".to_owned())?;
            TimelineClipPayload::Animation {
                animation_set: dropped.asset_id.clone(),
                motion_slot,
            }
        }
        _ => {
            return Err(format!(
                "{} is not compatible with the {} Timeline lane",
                dropped.relative_path.display(),
                track_kind_label(track.kind)
            ))
        }
    };
    let duration = TimelineTick::new(TIMELINE_TICKS_PER_SECOND.max(state.frame_ticks()));
    let clip = TimelineClip {
        id: engine_authoring::TimelineClipId::generate(),
        name: dropped
            .relative_path
            .file_stem()
            .and_then(|name| name.to_str())
            .unwrap_or("Clip")
            .to_owned(),
        start: state.playhead,
        duration,
        source_offset: TimelineTick::ZERO,
        payload,
    };
    state
        .apply(vec![engine_authoring::TimelineAuthoringCommand::AddClip {
            track: track.id.clone(),
            clip,
        }])
        .map_err(|error| error.to_string())
}

fn handle_clip_gesture(
    _ui: &mut egui::Ui,
    state: &mut TimelineEditorState,
    clip: &TimelineClip,
    response: &egui::Response,
    kind: TimelineClipGestureKind,
    extra_edges: &[TimelineTick],
) {
    if response.drag_started() {
        state.clip_gesture = Some(TimelineClipGesture {
            clip: clip.id.clone(),
            kind,
            original_start: clip.start,
            original_duration: clip.duration,
            draft_start: clip.start,
            draft_duration: clip.duration,
            snap_target: None,
        });
    }
    if response.dragged()
        && let Some(mut gesture) = state
            .clip_gesture
            .clone()
            .filter(|gesture| gesture.clip == clip.id && gesture.kind == kind)
    {
        let delta = (response.drag_delta().x as f64 * state.ticks_per_pixel()).round() as i64;
        let original_end = gesture
            .original_start
            .saturating_add(gesture.original_duration.get());
        match kind {
            TimelineClipGestureKind::Move => {
                let raw = gesture.original_start.saturating_add(delta);
                let (snapped, target) = state.snap_tick(raw, extra_edges);
                gesture.draft_start = snapped;
                gesture.snap_target = target;
            }
            TimelineClipGestureKind::TrimStart => {
                let raw = gesture.original_start.saturating_add(delta);
                let max_start = original_end.saturating_add(-1);
                let (snapped, target) = state.snap_tick(raw.clamp(TimelineTick::ZERO, max_start), extra_edges);
                gesture.draft_start = snapped.min(max_start);
                gesture.draft_duration = TimelineTick::new(
                    original_end.get().saturating_sub(gesture.draft_start.get()).max(1),
                );
                gesture.snap_target = target;
            }
            TimelineClipGestureKind::TrimEnd => {
                let raw = original_end.saturating_add(delta);
                let minimum = gesture.original_start.saturating_add(1);
                let (snapped, target) = state.snap_tick(raw.max(minimum), extra_edges);
                gesture.draft_duration = TimelineTick::new(
                    snapped.get().saturating_sub(gesture.original_start.get()).max(1),
                );
                gesture.snap_target = target;
            }
        }
        state.clip_gesture = Some(gesture);
    }
    if response.drag_stopped()
        && let Some(gesture) = state.clip_gesture.take().filter(|gesture| gesture.clip == clip.id && gesture.kind == kind)
    {
        let commands = match gesture.kind {
            TimelineClipGestureKind::Move => vec![engine_authoring::TimelineAuthoringCommand::MoveClip {
                clip: clip.id.clone(),
                start: gesture.draft_start,
            }],
            TimelineClipGestureKind::TrimStart => vec![
                engine_authoring::TimelineAuthoringCommand::MoveClip { clip: clip.id.clone(), start: gesture.draft_start },
                engine_authoring::TimelineAuthoringCommand::ResizeClip { clip: clip.id.clone(), duration: gesture.draft_duration },
            ],
            TimelineClipGestureKind::TrimEnd => vec![engine_authoring::TimelineAuthoringCommand::ResizeClip {
                clip: clip.id.clone(),
                duration: gesture.draft_duration,
            }],
        };
        apply_timeline_commands(state, commands);
    }
}

fn draw_timeline_ruler(
    ui: &egui::Ui,
    state: &TimelineEditorState,
    rect: egui::Rect,
    duration: TimelineTick,
    markers: &[TimelineMarker],
) {
    ui.painter().rect_filled(rect, 0.0, egui::Color32::from_gray(30));
    let frame = state.frame_ticks().max(1);
    let visible_ticks = (rect.width() as f64 * state.ticks_per_pixel()).ceil() as i64;
    let end = state.view_start.saturating_add(visible_ticks).min(duration);
    let mut tick = TimelineTick::new(state.view_start.get().div_euclid(frame) * frame);
    let label_stride = ((80.0 * state.ticks_per_pixel()) / frame as f64).ceil().max(1.0) as i64;
    let mut index = 0_i64;
    while tick <= end {
        let x = timeline_x(state, rect, tick);
        let major = index.rem_euclid(label_stride) == 0;
        ui.painter().line_segment(
            [egui::pos2(x, rect.bottom() - if major { 16.0 } else { 8.0 }), egui::pos2(x, rect.bottom())],
            egui::Stroke::new(1.0, if major { egui::Color32::LIGHT_GRAY } else { egui::Color32::DARK_GRAY }),
        );
        if major {
            ui.painter().text(
                egui::pos2(x + 3.0, rect.top() + 3.0),
                egui::Align2::LEFT_TOP,
                format!("{:.2}s", tick.to_seconds_f64()),
                egui::TextStyle::Small.resolve(ui.style()),
                egui::Color32::LIGHT_GRAY,
            );
        }
        tick = tick.saturating_add(frame);
        index += 1;
    }
    for marker in markers {
        let x = timeline_x(state, rect, marker.tick);
        if rect.contains(egui::pos2(x, rect.center().y)) {
            ui.painter().line_segment(
                [egui::pos2(x, rect.top()), egui::pos2(x, rect.bottom())],
                egui::Stroke::new(1.0, egui::Color32::from_rgb(230, 190, 70)),
            );
        }
    }
    let x = timeline_x(state, rect, state.playhead);
    ui.painter().line_segment(
        [egui::pos2(x, rect.top()), egui::pos2(x, rect.bottom())],
        egui::Stroke::new(2.0, egui::Color32::from_rgb(255, 110, 90)),
    );
}

fn draw_marker_lane(ui: &egui::Ui, state: &TimelineEditorState, rect: egui::Rect, markers: &[TimelineMarker]) {
    ui.painter().rect_filled(rect, 0.0, egui::Color32::from_gray(26));
    for marker in markers {
        let x = timeline_x(state, rect, marker.tick);
        if x >= rect.left() && x <= rect.right() {
            let points = [
                egui::pos2(x, rect.top() + 4.0),
                egui::pos2(x + 5.0, rect.top() + 9.0),
                egui::pos2(x, rect.top() + 14.0),
                egui::pos2(x - 5.0, rect.top() + 9.0),
            ];
            ui.painter().add(egui::Shape::convex_polygon(
                points.to_vec(),
                egui::Color32::from_rgb(230, 190, 70),
                egui::Stroke::NONE,
            ));
        }
    }
}

fn draw_timeline_lane_background(ui: &egui::Ui, state: &TimelineEditorState, rect: egui::Rect) {
    ui.painter().rect_filled(rect, 0.0, egui::Color32::from_gray(24));
    let frame = state.frame_ticks().max(1);
    let visible_ticks = (rect.width() as f64 * state.ticks_per_pixel()).ceil() as i64;
    let end = state.view_start.saturating_add(visible_ticks);
    let mut tick = TimelineTick::new(state.view_start.get().div_euclid(frame) * frame);
    while tick <= end {
        let x = timeline_x(state, rect, tick);
        ui.painter().line_segment(
            [egui::pos2(x, rect.top()), egui::pos2(x, rect.bottom())],
            egui::Stroke::new(0.5, egui::Color32::from_gray(38)),
        );
        tick = tick.saturating_add(frame);
    }
}

fn show_curve_editor(
    ui: &mut egui::Ui,
    keys: &mut Vec<TimelinePropertyKey>,
    duration: TimelineTick,
    changed: &mut bool,
) {
    ui.separator();
    ui.strong("Curve Editor");
    let (rect, _) = ui.allocate_exact_size(egui::vec2(ui.available_width(), 110.0), egui::Sense::hover());
    ui.painter().rect_filled(rect, 3.0, egui::Color32::from_gray(20));
    let values = keys
        .iter()
        .filter_map(|key| curve_scalar(&key.value).map(|value| (key.tick, value)))
        .collect::<Vec<_>>();
    if values.len() >= 2 {
        let min = values.iter().map(|(_, value)| *value).fold(f64::INFINITY, f64::min);
        let max = values.iter().map(|(_, value)| *value).fold(f64::NEG_INFINITY, f64::max);
        let span = (max - min).abs().max(1.0e-6);
        let points = values
            .iter()
            .map(|(tick, value)| {
                let x = rect.left() + rect.width() * (tick.get() as f32 / duration.get().max(1) as f32);
                let y = rect.bottom() - rect.height() * ((*value - min) / span) as f32;
                egui::pos2(x, y)
            })
            .collect::<Vec<_>>();
        ui.painter().add(egui::Shape::line(points, egui::Stroke::new(1.5, egui::Color32::LIGHT_BLUE)));
    }
    for (index, key) in keys.iter_mut().enumerate() {
        ui.push_id(("timeline_key", index), |ui| {
            ui.horizontal(|ui| {
                let mut tick = key.tick.get();
                *changed |= ui.add(egui::DragValue::new(&mut tick).prefix("t " )).changed();
                key.tick = TimelineTick::new(tick.clamp(0, duration.get()));
                match &mut key.value {
                    TimelinePropertyValue::Bool(value) => *changed |= ui.checkbox(value, "value").changed(),
                    TimelinePropertyValue::Number(value) => *changed |= ui.add(egui::DragValue::new(value).speed(0.01)).changed(),
                    TimelinePropertyValue::Vec3(value) => {
                        for component in value { *changed |= ui.add(egui::DragValue::new(component).speed(0.01)).changed(); }
                    }
                    TimelinePropertyValue::Quat(value) => {
                        for component in value { *changed |= ui.add(egui::DragValue::new(component).speed(0.01)).changed(); }
                    }
                }
            });
        });
    }
    if *changed {
        keys.sort_by_key(|key| key.tick);
    }
}

fn curve_scalar(value: &TimelinePropertyValue) -> Option<f64> {
    match value {
        TimelinePropertyValue::Bool(value) => Some(if *value { 1.0 } else { 0.0 }),
        TimelinePropertyValue::Number(value) => Some(*value),
        TimelinePropertyValue::Vec3(value) => Some(value[0]),
        TimelinePropertyValue::Quat(value) => Some(value[0]),
    }
}

fn timeline_x(state: &TimelineEditorState, rect: egui::Rect, tick: TimelineTick) -> f32 {
    rect.left()
        + ((tick.get() - state.view_start.get()) as f64 / TIMELINE_TICKS_PER_SECOND as f64
            * state.pixels_per_second() as f64) as f32
}

fn timeline_tick_at_x(
    state: &TimelineEditorState,
    rect: egui::Rect,
    x: f32,
    duration: TimelineTick,
) -> TimelineTick {
    let pixels = (x - rect.left()).max(0.0) as f64;
    let delta = (pixels * state.ticks_per_pixel()).round() as i64;
    state
        .view_start
        .saturating_add(delta)
        .clamp(TimelineTick::ZERO, duration)
}

fn track_kind_label(kind: TimelineTrackKind) -> &'static str {
    timeline_track_registry()
        .iter()
        .find(|descriptor| descriptor.kind == kind)
        .map_or("Timeline", |descriptor| descriptor.label)
}

fn binding_label(binding: &TimelineBinding) -> String {
    match binding {
        TimelineBinding::Entity { entity } => format!("Entity {}", entity.as_str()),
        TimelineBinding::Asset { asset } => format!("Asset {}", asset.as_str()),
    }
}

fn timeline_track_color(kind: TimelineTrackKind, selected: bool) -> egui::Color32 {
    let base = match kind {
        TimelineTrackKind::Animation => egui::Color32::from_rgb(80, 130, 210),
        TimelineTrackKind::TransformProperty => egui::Color32::from_rgb(90, 170, 130),
        TimelineTrackKind::CameraCut => egui::Color32::from_rgb(150, 110, 210),
        TimelineTrackKind::Event => egui::Color32::from_rgb(200, 145, 70),
        TimelineTrackKind::Audio => egui::Color32::from_rgb(80, 170, 180),
        TimelineTrackKind::Vfx => egui::Color32::from_rgb(190, 90, 150),
    };
    if selected { base.gamma_multiply(1.2) } else { base }
}

fn rational_preview_rate(rate: f32) -> (i32, u32) {
    if (rate - 0.25).abs() < f32::EPSILON { (1, 4) }
    else if (rate - 0.5).abs() < f32::EPSILON { (1, 2) }
    else if (rate - 2.0).abs() < f32::EPSILON { (2, 1) }
    else if (rate - 4.0).abs() < f32::EPSILON { (4, 1) }
    else { (1, 1) }
}
